add_action( 'rest_api_init', function () { register_rest_route( 'nadlan-dbg/v1', '/rw2', array( 'methods' => 'GET', 'permission_callback' => function(){ return current_user_can('manage_options'); }, 'callback' => function () { $rules = (array) get_option('rewrite_rules'); $out = array(); $i = 0; foreach ( $rules as $k => $v ) { $i++; $out[] = $i . ' | ' . $k . ' => ' . $v; if ( strpos( $k, 'advertiser-center' ) !== false ) { break; } } return array_slice( $out, 0, 60 ); } ) ); } );